package io.github.diodeme.ji.telemetry;

import java.util.Objects;
import java.util.Optional;

/** Diagnostic outcome without raw exception messages or stack traces. */
public record SpanStatus(Kind kind, Optional<String> errorCode) {
    private static final SpanStatus OK = new SpanStatus(Kind.OK, Optional.empty());

    public SpanStatus {
        Objects.requireNonNull(kind, "kind");
        errorCode = errorCode == null ? Optional.empty() : errorCode;
        if (kind == Kind.OK && errorCode.isPresent()) throw new IllegalArgumentException("ok status cannot carry an error code");
    }

    public static SpanStatus ok() {
        return OK;
    }

    public static SpanStatus error(String errorCode) {
        return new SpanStatus(Kind.ERROR, Optional.of(errorCode));
    }

    public static SpanStatus error() {
        return new SpanStatus(Kind.ERROR, Optional.empty());
    }

    public enum Kind { OK, ERROR }
}
